		terminalService = addPlugin(tool, typeof(TerminalPlugin));
		clipboardService = addPlugin(tool, typeof(ClipboardPlugin));
		env.showFrontEndTool();

		using (Terminal term = terminalService.createNullTerminal(Charset.forName("utf8"), @out => {
			@out.reset())
using (}))
{
			term.injectDisplayOutput(b);
			term.injectDisplayOutput("\u001b[1D".getBytes("utf8"));

			assertEquals(1, term.getCursorColumn());
		}
	}

